#!/usr/bin/env node
import { createHash } from "node:crypto";
import { access, readFile, readdir } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import { parse as parseYaml } from "yaml";

const projectRoot = path.resolve(import.meta.dirname, "..");
const generatedHeader =
  "<!-- Generated by scripts/migrate-legacy-content.mjs. -->";
const collectionRoots = {
  blog: path.join(projectRoot, "src/content/blog"),
  drafts: path.join(projectRoot, "src/content/drafts"),
  pages: path.join(projectRoot, "src/content/pages"),
};
const expected = { blog: 84, drafts: 19, pages: 3 };
const failures = [];

async function exists(file) {
  try {
    await access(file);
    return true;
  } catch {
    return false;
  }
}

async function markdownFiles(directory) {
  if (!(await exists(directory))) return [];
  return (await readdir(directory, { withFileTypes: true }))
    .filter((entry) => entry.isFile() && entry.name.endsWith(".md"))
    .map((entry) => path.join(directory, entry.name))
    .sort();
}

function parseDocument(text, file) {
  const match = text.match(/^---\s*\n([\s\S]*?)\n---\s*(?:\n|$)/);
  if (!match) throw new Error(`${file}: missing front matter`);
  return { data: parseYaml(match[1]) ?? {}, body: text.slice(match[0].length) };
}

const manifest = JSON.parse(
  await readFile(
    path.join(projectRoot, "docs/audit/url-manifest-v1.json"),
    "utf8",
  ),
);
const approvedPaths = new Set(
  manifest.articles.map((article) => article.legacyPath),
);
const seenPaths = new Set();

for (const [kind, root] of Object.entries(collectionRoots)) {
  const files = await markdownFiles(root);
  if (files.length !== expected[kind])
    failures.push(
      `${kind}: expected ${expected[kind]} Markdown files, found ${files.length}`,
    );

  for (const file of files) {
    const relative = path.relative(projectRoot, file);
    const text = await readFile(file, "utf8");
    let document;
    try {
      document = parseDocument(text, relative);
    } catch (error) {
      failures.push(error.message);
      continue;
    }
    const { data, body } = document;
    if (!text.includes(generatedHeader))
      failures.push(`${relative}: missing generated-file marker`);
    if (/<!--\s*more\s*-->/i.test(body))
      failures.push(`${relative}: contains a Hexo more marker`);
    if (/\{%\s*github_emoji/i.test(body))
      failures.push(`${relative}: contains a Hexo emoji tag`);
    if (new RegExp(`[${String.fromCharCode(8)}\\uFEFF]`).test(body))
      failures.push(`${relative}: contains a legacy control character`);
    if (/(?:\.\.\/|\.\/)images\//.test(body))
      failures.push(`${relative}: contains a relative image path`);
    const unresolvedLegacyImage = body.match(
      /(?:\(|src=["'])(\/images\/(?!missing-legacy-image\.svg)[^?"')\s]+)/,
    );
    if (unresolvedLegacyImage) {
      const target = path.join(
        projectRoot,
        "public",
        decodeURIComponent(unresolvedLegacyImage[1]).replace(/^\//, ""),
      );
      if (!(await exists(target)))
        failures.push(
          `${relative}: references missing local image ${unresolvedLegacyImage[1]}`,
        );
    }

    if (kind === "blog") {
      if (!data.description)
        failures.push(`${relative}: description is required`);
      if (data.draft !== false)
        failures.push(`${relative}: published article must have draft=false`);
      if (!approvedPaths.has(data.legacyPath))
        failures.push(
          `${relative}: legacyPath is not in URL manifest: ${data.legacyPath}`,
        );
      if (seenPaths.has(data.legacyPath))
        failures.push(`${relative}: duplicate legacyPath: ${data.legacyPath}`);
      seenPaths.add(data.legacyPath);
    }
    if (kind === "drafts" && data.draft !== true)
      failures.push(`${relative}: draft must have draft=true`);
  }
}

if (seenPaths.size !== approvedPaths.size)
  failures.push(
    `URL coverage: expected ${approvedPaths.size}, found ${seenPaths.size}`,
  );

const requiredCompatibilityFiles = [
  {
    name: "google3756ddc34336b7b9.html",
    sha256: "f7ed8bf2e292a6cdbac62bc98292a6baf14f3b7d7140005c56aaa287c6e7aadd",
  },
  {
    name: "keybase.txt",
    sha256: "fb4dc999ec6679efc7f4e27f0869ddd867c7fc61cebd335c02cc54f3857539c5",
  },
  {
    name: "CNAME",
    sha256: "b1ff7f1097c99c2e7fccf577eaddc4257244e7926fc2fb1af84b3b2079a8e8df",
  },
];
for (const { name, sha256 } of requiredCompatibilityFiles) {
  const target = path.join(projectRoot, "public", name);
  if (!(await exists(target))) {
    failures.push(`public/${name}: required compatibility file missing`);
    continue;
  }
  const targetBytes = await readFile(target);
  const actualHash = createHash("sha256").update(targetBytes).digest("hex");
  if (actualHash !== sha256)
    failures.push(
      `public/${name}: compatibility checksum changed (${actualHash} !== ${sha256})`,
    );
}
if (
  !(await exists(
    path.join(projectRoot, "public/images/missing-legacy-image.svg"),
  ))
)
  failures.push("public/images/missing-legacy-image.svg: placeholder missing");

const reportPath = path.join(
  projectRoot,
  "docs/audit/content-migration-report.json",
);
if (!(await exists(reportPath)))
  failures.push(
    "docs/audit/content-migration-report.json: migration report missing",
  );
else {
  const report = JSON.parse(await readFile(reportPath, "utf8"));
  for (const [kind, count] of Object.entries(expected))
    if (report.counts?.[kind] !== count)
      failures.push(
        `report count ${kind}: expected ${count}, found ${report.counts?.[kind]}`,
      );
}

if (failures.length) {
  console.error(
    `Content migration validation failed with ${failures.length} error(s):`,
  );
  for (const failure of failures) console.error(`- ${failure}`);
  process.exit(1);
}

const digest = createHash("sha256");
for (const root of Object.values(collectionRoots))
  for (const file of await markdownFiles(root))
    digest.update(await readFile(file));
console.log(
  `Content migration valid: 84 articles, 19 private drafts, 3 authored pages, 84 approved historical paths. Digest ${digest.digest("hex")}.`,
);
